package com.kazemieh.rasteh.identity.agent

import com.kazemieh.rasteh.identity.authorization.*
import com.kazemieh.rasteh.identity.membership.persistence.AuthorizationAuditRepository
import com.kazemieh.rasteh.identity.membership.persistence.entity.AuthorizationAuditEntity
import com.kazemieh.rasteh.shared.error.BadRequestException
import com.kazemieh.rasteh.shared.error.NotFoundException
import jakarta.persistence.*
import org.springframework.data.jpa.repository.JpaRepository
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional
import org.springframework.web.bind.annotation.*
import org.springframework.security.core.annotation.AuthenticationPrincipal
import com.kazemieh.rasteh.shared.security.UserPrincipal
import java.time.OffsetDateTime
import java.util.UUID

enum class DraftStatus { DRAFT, SUBMITTED, APPROVED, REJECTED }
@Entity @Table(name="agent_assignments") class AgentAssignment(@Id var id:UUID=UUID.randomUUID(),@Column(name="agent_user_id") var agentUserId:Long=0,@Column(name="supervisor_user_id") var supervisorUserId:Long?=null,@Column(name="cluster_key") var clusterKey:String="",var active:Boolean=true,@Column(name="created_by_user_id") var createdByUserId:Long?=null)
@Entity @Table(name="agent_drafts") class AgentDraft(@Id var id:UUID=UUID.randomUUID(),@Column(name="agent_user_id") var agentUserId:Long=0,@Column(name="assignment_id") var assignmentId:UUID=UUID.randomUUID(),@Enumerated(EnumType.STRING) var status:DraftStatus=DraftStatus.DRAFT,@Column(columnDefinition="jsonb") var payload:String="{}",@Column(name="consent_recorded_at") var consentRecordedAt:OffsetDateTime?=null,@Column(name="submitted_at") var submittedAt:OffsetDateTime?=null,@Column(name="reviewed_by_user_id") var reviewedByUserId:Long?=null,@Column(name="reviewed_at") var reviewedAt:OffsetDateTime?=null,@Column(name="review_decision") var reviewDecision:String?=null,@Column(name="review_note") var reviewNote:String?=null)
interface AgentAssignmentRepository:JpaRepository<AgentAssignment,UUID> { fun findByIdAndAgentUserIdAndActiveTrue(id:UUID,userId:Long):AgentAssignment? }
interface AgentDraftRepository:JpaRepository<AgentDraft,UUID> { fun findAllByStatus(status:DraftStatus):List<AgentDraft> }
data class AssignmentRequest(val agentUserId:Long,val clusterKey:String); data class DraftRequest(val assignmentId:UUID,val payload:String,val consent:Boolean); data class ReviewRequest(val approved:Boolean,val note:String?=null)
@Service class AgentWorkflowService(private val auth:AuthorizationService,private val assignments:AgentAssignmentRepository,private val drafts:AgentDraftRepository,private val audit:AuthorizationAuditRepository) {
 @Transactional fun assign(actor:Long,r:AssignmentRequest):AgentAssignment { auth.require(actor,Capability.AGENT_ASSIGN); return assignments.save(AgentAssignment(agentUserId=r.agentUserId,supervisorUserId=actor,clusterKey=r.clusterKey,createdByUserId=actor)).also { log(actor,r.agentUserId,"AGENT_ASSIGNED") } }
 @Transactional fun saveDraft(agent:Long,r:DraftRequest):AgentDraft { auth.require(agent,Capability.AGENT_DRAFT_WRITE); assignments.findByIdAndAgentUserIdAndActiveTrue(r.assignmentId,agent)?:throw BadRequestException("Assignment is inactive or belongs to another agent","ASSIGNMENT_DENIED"); val d=AgentDraft(agentUserId=agent,assignmentId=r.assignmentId,payload=r.payload); if(r.consent)d.consentRecordedAt=OffsetDateTime.now(); return drafts.save(d).also { log(agent,agent,"AGENT_DRAFT_CREATED") } }
 @Transactional fun editDraft(agent:Long,id:UUID,r:DraftRequest):AgentDraft { auth.require(agent,Capability.AGENT_DRAFT_WRITE); val d=drafts.findById(id).orElseThrow{NotFoundException("Draft not found","DRAFT_NOT_FOUND")}; if(d.agentUserId!=agent||d.status!=DraftStatus.DRAFT)throw BadRequestException("Only own unsubmitted draft may be edited","DRAFT_EDIT_DENIED"); assignments.findByIdAndAgentUserIdAndActiveTrue(d.assignmentId,agent)?:throw BadRequestException("Assignment is inactive","ASSIGNMENT_DENIED"); d.payload=r.payload;if(r.consent&&d.consentRecordedAt==null)d.consentRecordedAt=OffsetDateTime.now();return drafts.save(d).also{log(agent,agent,"AGENT_DRAFT_EDITED")} }
 @Transactional fun submit(agent:Long,id:UUID):AgentDraft { auth.require(agent,Capability.AGENT_DRAFT_SUBMIT); val d=drafts.findById(id).orElseThrow{NotFoundException("Draft not found","DRAFT_NOT_FOUND")}; if(d.agentUserId!=agent||d.status!=DraftStatus.DRAFT||d.consentRecordedAt==null) throw BadRequestException("Only own consented draft may be submitted","DRAFT_SUBMIT_DENIED"); d.status=DraftStatus.SUBMITTED;d.submittedAt=OffsetDateTime.now();return drafts.save(d).also{log(agent,agent,"AGENT_DRAFT_SUBMITTED")} }
 @Transactional fun review(reviewer:Long,id:UUID,r:ReviewRequest):AgentDraft { auth.require(reviewer,Capability.AGENT_DRAFT_REVIEW);val d=drafts.findById(id).orElseThrow{NotFoundException("Draft not found","DRAFT_NOT_FOUND")};if(d.agentUserId==reviewer||d.status!=DraftStatus.SUBMITTED)throw BadRequestException("Maker cannot review own draft","MAKER_CHECKER_VIOLATION");d.status=if(r.approved)DraftStatus.APPROVED else DraftStatus.REJECTED;d.reviewedByUserId=reviewer;d.reviewedAt=OffsetDateTime.now();d.reviewDecision=d.status.name;d.reviewNote=r.note;return drafts.save(d).also{log(reviewer,d.agentUserId,"AGENT_DRAFT_REVIEWED")} }
 fun queue(reviewer:Long):List<AgentDraft>{auth.require(reviewer,Capability.AGENT_DRAFT_REVIEW);return drafts.findAllByStatus(DraftStatus.SUBMITTED)}; private fun log(actor:Long,subject:Long,action:String)=audit.save(AuthorizationAuditEntity(actorUserId=actor,subjectUserId=subject,action=action))
}
@RestController @RequestMapping("/api/agent") class AgentWorkflowController(private val s:AgentWorkflowService){@PostMapping("/assignments") fun assign(@AuthenticationPrincipal p:UserPrincipal,@RequestBody r:AssignmentRequest)=s.assign(p.id,r);@PostMapping("/drafts") fun draft(@AuthenticationPrincipal p:UserPrincipal,@RequestBody r:DraftRequest)=s.saveDraft(p.id,r);@PutMapping("/drafts/{id}") fun edit(@AuthenticationPrincipal p:UserPrincipal,@PathVariable id:UUID,@RequestBody r:DraftRequest)=s.editDraft(p.id,id,r);@PostMapping("/drafts/{id}/submit") fun submit(@AuthenticationPrincipal p:UserPrincipal,@PathVariable id:UUID)=s.submit(p.id,id);@GetMapping("/review-queue") fun queue(@AuthenticationPrincipal p:UserPrincipal)=s.queue(p.id);@PostMapping("/drafts/{id}/review") fun review(@AuthenticationPrincipal p:UserPrincipal,@PathVariable id:UUID,@RequestBody r:ReviewRequest)=s.review(p.id,id,r)}
